SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE IS_DELETED = 0

    AND TENANT_ID = #{param.tenantId}


    AND BOOK_ID = #{param.bookId}


    AND FACTOR_CODE LIKE '%' || #{param.factorCode} || '%'


    AND FACTOR_NAME LIKE '%' || #{param.factorName} || '%'


    AND FACTOR_TYPE = #{param.factorType}


    AND IS_ENABLED = #{param.isEnabled}

ORDER BY PRIORITY_LEVEL ASC, CREATE_TIME DESC

SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_CODE = #{factorCode}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0
AND ROWNUM = 1

SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_TYPE = #{factorType}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0
AND IS_ENABLED = 1
ORDER BY FACTOR_CODE ASC

SELECT COUNT(1)
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_CODE = #{factorCode}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0

    AND ID != #{excludeId}

