UPDATE TBL_INFLUENCE_FACTOR SET IS_ENABLED = #{isEnabled}, UPDATE_TIME = SYSDATE, UPDATER = #{updater} WHERE ID IN
#{factorId}
AND IS_DELETED = 0

UPDATE TBL_INFLUENCE_FACTOR SET IS_DELETED = 1, UPDATE_TIME = SYSDATE, UPDATER = #{updater} WHERE ID IN
#{factorId}
AND IS_DELETED = 0

UPDATE TBL_INFLUENCE_FACTOR
FACTOR_CODE = #{factorCode}, FACTOR_NAME = #{factorName}, FACTOR_TYPE = #{factorType}, DATA_TYPE = #{dataType}, FACTOR_VALUE = #{factorValue}, DEFAULT_VALUE = #{defaultValue}, CALCULATION_FORMULA = #{calculationFormula}, AFFECT_SCOPE = #{affectScope}, PRIORITY_LEVEL = #{priorityLevel}, IS_ENABLED = #{isEnabled}, DESCRIPTION = #{description}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy},
WHERE ID = #{factorId}
